package com.myles.cijian;

import android.app.*;import android.os.*;import android.content.*;import android.content.pm.*;import android.provider.Settings;import org.json.*;import java.nio.charset.StandardCharsets;import java.util.*;

/** 真实旧版JSON跨应用迁移及新格式回读，仅在专用模拟器执行。 / Cross-app migration from an actual legacy JSON fixture; emulator only. */
public final class Feature111Migration extends Instrumentation {
    private int checks,legacyUid;
    private void check(boolean yes,String label){if(!yes)throw new AssertionError(label);checks++;}
    @Override public void onCreate(Bundle args){super.onCreate(args);legacyUid=Integer.parseInt(args.getString("legacy_uid"));start();}
    private String normalized(JSONArray rows)throws Exception{List<String> values=new ArrayList<>();for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);TreeMap<String,String> sorted=new TreeMap<>();for(Iterator<String> keys=row.keys();keys.hasNext();){String key=keys.next();sorted.put(key,String.valueOf(row.get(key)));}values.add(sorted.toString());}Collections.sort(values);return values.toString();}
    private void records(JSONObject expected,JSONObject actual)throws Exception{for(String key:new String[]{"progress","encounters","exposures","reviews","review_started","review_days","weak_words","mark_changes"})check(normalized(expected.getJSONArray(key)).equals(normalized(actual.getJSONArray(key))),"Migration preserves "+key);}
    @Override public void onStart(){Bundle result=new Bundle();try{
        if(!Build.HARDWARE.equals("ranchu")&&!Build.HARDWARE.equals("goldfish"))throw new AssertionError("Emulator only");Context c=getTargetContext();check(c.getPackageName().equals("com.myles.cijian"),"New application identity");check(legacyUid>0&&legacyUid!=c.getApplicationInfo().uid,"New and old apps have different UIDs");check(!c.getDatabasePath("cijian.db").exists(),"New app has a fresh database before import");
        String json=new String(java.nio.file.Files.readAllBytes(new java.io.File(c.getFilesDir(),"legacy-backup.json").toPath()),StandardCharsets.UTF_8);JSONObject legacy=new JSONObject(json);check(legacy.getString("format").equals("kotoba-float-progress-v2"),"Fixture is the real old export format");BackupPreview.inspect(json);checks++;
        WordStore store=WordStore.get(c);JSONObject empty=new JSONObject(store.backup());check(empty.getString("format").equals(BackupFormat.CURRENT),"Fresh export uses Cijian format");check(empty.getJSONArray("progress").length()==0,"No automatic access to old records");Prefs prefs=new Prefs(c);prefs.put("appWordSize",34);
        RestoreSafety.apply(c,store,json,false,false);JSONObject recordsOnly=new JSONObject(store.backup());records(legacy,recordsOnly);check(prefs.data.getInt("appWordSize",0)==34,"Records-only import leaves local settings");check(RestoreSafety.available(c),"Import snapshot can be undone");RestoreSafety.undo(c,store);check(new JSONObject(store.backup()).getJSONArray("progress").length()==0,"Undo restores pre-import records");
        RestoreSafety.apply(c,store,json,true,false);JSONObject restored=new JSONObject(store.backup());records(legacy,restored);JSONObject expected=legacy.getJSONObject("preferences"),actual=restored.getJSONObject("preferences");for(Iterator<String> keys=expected.keys();keys.hasNext();){String key=keys.next();check(actual.has(key)&&expected.get(key).equals(actual.get(key)),"Migrated setting "+key);}
        for(String mode:new String[]{"TASK","LIGHT","DUE","PRACTICE","WEAK"})check(store.draft(mode)==null,"Unfinished batches are rescheduled rather than copied");check(!prefs.data.getBoolean("session.enabled",false)&&!FloatService.running,"Import does not start floating study");check(c.getDatabasePath("cijian.db").exists()&&!c.getDatabasePath("kotoba.db").exists(),"New database uses only Cijian name");
        BackupPreview.inspect(restored.toString());checks++;JSONObject v1=new JSONObject().put("format","kotoba-float-progress-v1").put("progress",legacy.getJSONArray("progress")).put("encounters",legacy.getJSONArray("encounters"));BackupPreview.inspect(v1.toString());checks++;check(!BackupFormat.supported("unknown-progress-v2"),"Unrelated formats are rejected");check(BackupFormat.supported("cijian-progress-v2")&&BackupFormat.supported("kotoba-float-progress-v2")&&BackupFormat.supported("kotoba-float-progress-v1"),"Current and legacy formats are recognized");
        java.io.File file=BackupFiles.create(c,store.backup());check(file.getName().startsWith("cijian-backup-"),"New exported filename uses Cijian");android.net.Uri uri=BackupFiles.share(c,file).getParcelableExtra(Intent.EXTRA_STREAM);check(uri.getAuthority().equals("com.myles.cijian.backups"),"New backup sharing authority");try(java.io.InputStream in=c.getContentResolver().openInputStream(uri)){check(in!=null&&in.read()>=0,"New shared backup can be read");}
        result.putString("stream","PASS: "+checks+" cross-app migration and backup compatibility checks\n");finish(Activity.RESULT_OK,result);
    }catch(Throwable e){result.putString("stream","FAIL: "+android.util.Log.getStackTraceString(e));finish(Activity.RESULT_CANCELED,result);}}
}
